            ->select('p')
            ->from(Purchase::class, 'p')
            ->where('p.id = :id AND p.customer = :customer')
            ->setParameter('id', $id)
            ->setParameter('customer', $customer)
            ->getQuery()
            ->getOneOrNullResult();

        return null === $purchase ? null : $this->mapper->purchase($purchase);
    }

