<?php

namespace App\Api\Listener;

use Symfony\Component\EventDispatcher\Attribute\AsEventListener;
use Symfony\Component\HttpKernel\Event\RequestEvent;
use Symfony\Component\HttpKernel\KernelEvents;

/**
 * API Platform documents OpenAPI 3.2 unless asked otherwise with the spec_version query parameter: the document served
 * at /openapi.json is 3.0.0, which is what clients of this API read.
 */
#[AsEventListener(event: KernelEvents::REQUEST, priority: 64)]
final class OpenApiVersionListener
{
    public function __invoke(RequestEvent $event): void
    {
        $request = $event->getRequest();

        if ($event->isMainRequest() && '/openapi.json' === $request->getPathInfo() && !$request->query->has('spec_version')) {
            $request->query->set('spec_version', '3.0.0');
        }
    }
}
